const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (typeof $json.tender_id !== 'string' || !uuid.test($json.tender_id) || typeof $json.org_id !== 'string' || !uuid.test($json.org_id)) {
  throw new Error('INVALID_TENANT_CONTEXT');
}
return [{ json: $json }];

const tender = $('load-requirements').first().json;
const profile = $('load-company-profile').first().json || {};
const asArray = (value) => Array.isArray(value) ? value : [];
const asObject = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const asIntegerOrNull = (value) => Number.isInteger(value) ? value : null;
const rawProjectReferences = asArray(profile.project_references);
const projectReferences = rawProjectReferences.filter((reference) =>
  reference && typeof reference === 'object' &&
  typeof reference.client === 'string' && reference.client.trim().length > 0 &&
  typeof reference.project === 'string' && reference.project.trim().length > 0);
const projectReferencesState = projectReferences.length > 0
  ? 'provided'
  : profile.project_references_state === 'explicitly_absent'
    ? 'explicitly_absent'
    : 'not_provided';

// Business/evaluation fields only. Internal IDs, ownership, onboarding state and
// timestamps never enter the model context.
const companyProfile = {
  name: profile.name || 'Unbekanntes Unternehmen',
  founded_year: asIntegerOrNull(profile.founded_year),
  team_size: asIntegerOrNull(profile.team_size),
  annual_turnover_eur: asIntegerOrNull(profile.annual_turnover_eur),
  trades: asArray(profile.trades),
  regions: asArray(profile.regions),
  service_types: asArray(profile.service_types),
  certifications: asArray(profile.certifications),
  project_size_min_eur: asIntegerOrNull(profile.project_size_min_eur),
  project_size_max_eur: asIntegerOrNull(profile.project_size_max_eur),
  trade_capacities: asArray(profile.trade_capacities),
  insurances: asObject(profile.insurances),
  policies: asObject(profile.policies),
  project_references: projectReferences,
  project_references_state: projectReferencesState,
  // HQ address for distance calculation (IMP-03b)
  hq_street:      profile.hq_street      || null,
  hq_postal_code: profile.hq_postal_code || null,
  hq_city:        profile.hq_city        || null,
};
const hasEvidenceValue = (value) =>
  value !== null && value !== undefined &&
  (typeof value !== 'string' || value.trim().length > 0) &&
  (!Array.isArray(value) || value.length > 0) &&
  (typeof value !== 'object' || Array.isArray(value) || Object.keys(value).length > 0);
const profileEvidenceContract = {
  version: 1,
  available_fields: Object.entries(companyProfile)
    .filter(([, value]) => hasEvidenceValue(value))
    .map(([field]) => field),
};
const scoreMethodology = {
  version: 1,
  component_maxima: {
    trade_scope_fit: 25,
    capacity_project_size_fit: 20,
    region_delivery_model_fit: 15,
    references_qualifications_fit: 25,
    execution_value_creation_fit: 15,
  },
  neutral_components: {
    trade_scope_fit: 13,
    capacity_project_size_fit: 10,
    region_delivery_model_fit: 8,
    references_qualifications_fit: 12,
    execution_value_creation_fit: 7,
  },
};

const requirements = tender.requirements || [];
const availableEvidence = new Set(profileEvidenceContract.available_fields);
const normalizeEvidenceText = (value) => String(value ?? '')
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLocaleLowerCase('de-DE')
  .replace(/[^a-z0-9äöüß]+/g, ' ')
  .trim();
const textTokens = (value) => new Set(normalizeEvidenceText(value)
  .split(' ')
  .filter((token) => token.length >= 3));
const profileValueMatches = (values, requirementText) => {
  const requirementTokens = textTokens(requirementText);
  return asArray(values).some((value) => {
    const tokens = [...textTokens(value)];
    return tokens.length > 0 && tokens.every((token) => requirementTokens.has(token));
  });
};
const truePolicyMatches = (policies, requirementText) => {
  const normalized = normalizeEvidenceText(requirementText);
  const termsByPolicy = {
    pays_living_wage: ['mindestlohn', 'tarif', 'entgelt'],
    modern_slavery_compliant: ['kinderarbeit', 'zwangsarbeit', 'menschenhandel'],
    equality_diversity_policy: ['gleichbehandlung', 'gleichstellung', 'diversitat', 'agg'],
    eu_sanctions_compliant: ['russland', 'sanktion'],
    gdpr_compliant: ['datenschutz', 'dsgvo'],
    sustainability_policy: ['nachhaltigkeit'],
  };
  return Object.entries(asObject(policies)).some(([key, value]) =>
    value === true && asArray(termsByPolicy[key]).some((term) => normalized.includes(term)));
};
const insuranceMatches = (insurances, requirementText) => {
  const normalized = normalizeEvidenceText(requirementText);
  const termsByInsurance = {
    public_liability: ['betriebshaftpflicht', 'haftpflicht'],
    employers_liability: ['arbeitgeberhaftpflicht'],
    professional_indemnity: ['berufshaftpflicht', 'vermogensschadenhaftpflicht'],
    product_liability: ['produkthaftpflicht'],
  };
  return Object.entries(asObject(insurances)).some(([key, value]) =>
    hasEvidenceValue(value) && asArray(termsByInsurance[key]).some((term) => normalized.includes(term)));
};
const requirementTextById = Object.fromEntries(requirements
  .filter((requirement) => typeof requirement?.id === 'string')
  .map((requirement) => [requirement.id, [requirement.title, requirement.description]
    .filter((value) => typeof value === 'string')
    .join(' ')]));
const evidenceFieldsFor = (requirement) => {
  const text = requirementTextById[requirement.id] || '';
  const normalized = normalizeEvidenceText(text);
  const fields = [];
  const add = (field) => {
    if (availableEvidence.has(field) && !fields.includes(field)) fields.push(field);
  };
  if (profileValueMatches(companyProfile.certifications, text)) add('certifications');
  if (insuranceMatches(companyProfile.insurances, text)) add('insurances');
  if (requirement.category === 'Referenz') {
    if (projectReferences.length > 0) add('project_references');
    add('project_references_state');
  }
  if (requirement.category === 'Personal' &&
    /(personal|arbeitskraft|arbeitskrafte|beschaftigt|mitarbeiter|team|lohngruppe)/.test(normalized)) {
    add('team_size');
    add('trade_capacities');
  } else if (companyProfile.trade_capacities.some((capacity) =>
    profileValueMatches([capacity?.trade], text))) {
    add('trade_capacities');
  }
  if (/(jahresumsatz|umsatz)/.test(normalized)) add('annual_turnover_eur');
  if (/(auftragswert|projektgroße|projektgrosse|projektvolumen)/.test(normalized)) {
    add('project_size_min_eur');
    add('project_size_max_eur');
  }
  if (truePolicyMatches(companyProfile.policies, text)) add('policies');
  return fields;
};
const requirementEvidenceFields = Object.fromEntries(requirements
  .filter((requirement) => typeof requirement?.id === 'string')
  .map((requirement) => [requirement.id, evidenceFieldsFor(requirement)]));
const requirementEvidencePolicy = Object.fromEntries(requirements
  .filter((requirement) => typeof requirement?.id === 'string')
  .map((requirement) => {
    const allowedFields = requirementEvidenceFields[requirement.id];
    const referenceExplicitlyAbsent = requirement.category === 'Referenz' &&
      projectReferencesState === 'explicitly_absent';
    const personnelEvidenceOnly = requirement.category === 'Personal' &&
      allowedFields.length > 0 &&
      allowedFields.every((field) => ['team_size', 'trade_capacities'].includes(field));
    const personnelNeedsHistoricalEvidence = personnelEvidenceOnly &&
      /(letzten \d+ jahr|jahresdurchschnitt|lohngruppe|leitungspersonal)/.test(
        normalizeEvidenceText(requirementTextById[requirement.id] || ''),
      );
    const allowedStatuses = referenceExplicitlyAbsent
      ? ['not_met']
      : allowedFields.length === 0 ||
          (requirement.category === 'Referenz' && projectReferencesState === 'not_provided') ||
          personnelNeedsHistoricalEvidence
        ? ['needs_review']
        : ['compliant', 'partial', 'needs_review'];
    return [requirement.id, {
      allowed_fields: allowedFields,
      allowed_statuses: allowedStatuses,
    }];
  }));
const referenceTerms = [
  'referenzprojekt', 'referenzobjekt', 'referenzleistung', 'referenznachweis',
  'vergleichbare projekte', 'vergleichbaren projekten', 'vergleichbare leistungen',
];
const referenceRequirementIds = requirements.filter((requirement) => {
  const text = [requirement?.title, requirement?.description]
    .filter((value) => typeof value === 'string')
    .join(' ')
    .toLocaleLowerCase('de-DE');
  return referenceTerms.some((term) => text.includes(term));
}).map((requirement) => requirement.id);
const referenceEvidenceUnknownIds = projectReferencesState === 'not_provided'
  ? referenceRequirementIds : [];
const referenceEvidenceAbsentIds = projectReferencesState === 'explicitly_absent'
  ? referenceRequirementIds : [];

// Bauort context for distance/travel risk assessment
const bauort = tender.region || null;

// Wertschöpfungsanalyse — from stage 2 classification
const vb = tender.value_breakdown || null;
const valueBreakdownNote = vb ? (function() {
  const s = vb.summary || {};
  const total = s.total || 1;
  const fremdPct = Math.round((s.fremd || 0) / total * 100);
  const lieferPct = Math.round((s.liefer || 0) / total * 100);
  const gemischtPct = Math.round((s.gemischt || 0) / total * 100);
  const eigenPct = 100 - fremdPct - lieferPct - gemischtPct;
  const parts = [];
  if (eigenPct > 0)    parts.push(eigenPct + '% Eigenleistung (' + s.eigen + ' Pos.)');
  if (fremdPct > 0)    parts.push(fremdPct + '% Fremdleistung (' + s.fremd + ' Pos.)');
  if (lieferPct > 0)   parts.push(lieferPct + '% Lieferleistung (' + s.liefer + ' Pos.)');
  if (gemischtPct > 0) parts.push(gemischtPct + '% Mischleistung (' + s.gemischt + ' Pos.)');
  return parts.join(', ');
})() : null;
const companyRegions = companyProfile.regions;
// Simple heuristic: flag if Bauort is not within any of the company's listed regions
// e.g. company covers 'Bayern', Bauort is 'Nordrhein-Westfalen' → outside service area
const bauortOutsideRegions = bauort && companyRegions.length > 0
  ? !companyRegions.some(r => bauort.toLowerCase().includes(r.toLowerCase()) || r.toLowerCase().includes(bauort.toLowerCase()))
  : false;

return [{ json: {
  tender_id: tender.id,
  company_profile: companyProfile,
  profile_evidence_contract: profileEvidenceContract,
  score_methodology: scoreMethodology,
  requirement_evidence_fields: requirementEvidenceFields,
  requirement_evidence_policy: requirementEvidencePolicy,
  requirements,
  requirements_json: JSON.stringify(requirements),
  reference_evidence_unknown_ids: referenceEvidenceUnknownIds,
  reference_evidence_absent_ids: referenceEvidenceAbsentIds,
  bauort,
  bauort_outside_regions: bauortOutsideRegions,
  company_regions_str: companyRegions.join(', ') || 'nicht angegeben',
  value_breakdown_note: valueBreakdownNote,
} }];

const trigger = $('trigger').first().json;
const companyEvidence = Array.isArray(trigger.company_requirement_evidence)
  ? trigger.company_requirement_evidence : [];
const tenderEvidence = Array.isArray(trigger.tender_requirement_evidence)
  ? trigger.tender_requirement_evidence : [];
const requirements = Array.isArray($json.requirements) ? $json.requirements : [];
const knownIds = new Set(requirements.map((requirement) => requirement?.id));
const commonStatuses = new Set(['pending', 'in_progress', 'verified', 'not_met']);
const exactStatuses = new Set([...commonStatuses, 'not_applicable']);
const boundedString = (value, maxLength) =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= maxLength;
const boundedOptional = (value, maxLength) => value === null ||
  (typeof value === 'string' && value.length <= maxLength);
const validCommon = (item, statuses) => item && typeof item === 'object' && !Array.isArray(item) &&
  boundedString(item.evidence_id, 100) && boundedString(item.title, 500) &&
  boundedString(item.category, 200) && statuses.has(item.status) &&
  boundedOptional(item.note, 2000) && boundedOptional(item.cert_reference, 500) &&
  boundedOptional(item.cert_expiry, 10) && typeof item.updated_at === 'string' &&
  item.updated_at.length <= 40 && Number.isFinite(Date.parse(item.updated_at));
if (companyEvidence.length > 50 || tenderEvidence.length > 25 || knownIds.size !== requirements.length) {
  throw new Error('INVALID_REQUIREMENT_EVIDENCE');
}
const companyIds = new Set();
for (const item of companyEvidence) {
  if (!validCommon(item, commonStatuses) || item.legacy_identity !== true ||
    companyIds.has(item.evidence_id)) throw new Error('INVALID_REQUIREMENT_EVIDENCE');
  companyIds.add(item.evidence_id);
}
const exactById = new Map();
for (const item of tenderEvidence) {
  if (!validCommon(item, exactStatuses) || !boundedString(item.requirement_id, 100) ||
    !knownIds.has(item.requirement_id) || exactById.has(item.requirement_id) ||
    (item.status === 'not_applicable' && !item.note?.trim())) {
    throw new Error('INVALID_REQUIREMENT_EVIDENCE');
  }
  exactById.set(item.requirement_id, item);
}
const normalize = (value) => String(value ?? '').normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('de-DE')
  .replace(/[^a-z0-9äöüß]+/g, ' ').trim();
const stop = new Set(['aktuell', 'aktuelle', 'aktueller', 'nachweis', 'erforderlich',
  'anforderung', 'unternehmen', 'vorhanden', 'sonstiges', 'sonstige']);
const tokens = (value) => normalize(value).split(' ')
  .filter((token) => token.length >= 5 && !stop.has(token));
const semanticallyMatches = (evidence, source) => {
  const evidenceTokens = tokens([evidence.title, evidence.category].join(' '));
  const sourceTokens = tokens([source?.title, source?.description, source?.category].join(' '));
  return evidenceTokens.some((left) => sourceTokens.some((right) => {
    const prefix = Math.min(8, left.length, right.length);
    return prefix >= 6 && left.slice(0, prefix) === right.slice(0, prefix);
  }));
};
const evidenceById = new Map(requirements.map((requirement) => [
  requirement.id,
  exactById.get(requirement.id) || companyEvidence.find((item) => semanticallyMatches(item, requirement)) || null,
]));
const allEvidence = [...companyEvidence, ...tenderEvidence];
let evidenceCutoffAt = null;
let evidenceCutoffTime = -Infinity;
for (const item of allEvidence) {
  const time = Date.parse(item.updated_at);
  if (time > evidenceCutoffTime) {
    evidenceCutoffTime = time;
    evidenceCutoffAt = item.updated_at;
  }
}
const hasMatchingEvidence = [...evidenceById.values()].some(Boolean);
const profileEvidenceContract = {
  ...$json.profile_evidence_contract,
  available_fields: [
    ...($json.profile_evidence_contract?.available_fields || []),
    ...(hasMatchingEvidence ? ['requirement_evidence'] : []),
  ],
};
const requirementEvidenceFields = Object.fromEntries(requirements.map((requirement) => {
  const current = Array.isArray($json.requirement_evidence_fields?.[requirement.id])
    ? $json.requirement_evidence_fields[requirement.id] : [];
  return [requirement.id, evidenceById.get(requirement.id)
    ? [...new Set([...current, 'requirement_evidence'])] : current];
}));
