  profile_evidence_contract: profileEvidenceContract,
  requirement_evidence_fields: requirementEvidenceFields,
  requirement_evidence_policy: requirementEvidencePolicy,
  requirements: enrichedRequirements,
  requirements_json: JSON.stringify({
    source_requirements: enrichedRequirements,
    reusable_company_evidence: companyEvidence,
