  company_requirement_evidence: companyEvidence,
  tender_requirement_evidence: tenderEvidence,
  requirement_evidence_by_id: Object.fromEntries([...evidenceById].filter(([, evidence]) => evidence)),
  evidence_cutoff_at: evidenceCutoffAt,
