  scoreComponentKeys.reduce((sum, key) => sum + value[key], 0) === score
);
const referenceEvidenceUnknownIds = new Set(
  Array.isArray(preparedContext.reference_evidence_unknown_ids)
    ? preparedContext.reference_evidence_unknown_ids : []
);
const referenceEvidenceAbsentIds = new Set(
  Array.isArray(preparedContext.reference_evidence_absent_ids)
    ? preparedContext.reference_evidence_absent_ids : []
);
const referenceReviewReason = 'Referenzprojekte wurden im Unternehmensprofil noch nicht hinterlegt.';

let evaluation;
let actualBlockingCount = 0;
try {
  const content = $json.choices?.[0]?.message?.content;
  const rawEvaluation = typeof content === 'string'
    ? JSON.parse(content.replace(/\x60\x60\x60json|\x60\x60\x60/g, '').trim())
    : content;
  if (!isObject(rawEvaluation)) throw new Error('invalid response');

  const strengths = rawEvaluation.strengths == null ? [] : parseIfString(rawEvaluation.strengths);
  const eligibilityRequirements = parseIfString(rawEvaluation.eligibility_requirements);
  const risks = rawEvaluation.risks == null ? [] : parseIfString(rawEvaluation.risks);
  const clarifications = rawEvaluation.clarifications == null ? [] : parseIfString(rawEvaluation.clarifications);
  if (
    !Number.isInteger(rawEvaluation.strategic_fit_score) ||
    rawEvaluation.strategic_fit_score < 0 ||
    rawEvaluation.strategic_fit_score > 100 ||
    !validScoreComponents(rawEvaluation.score_components, rawEvaluation.strategic_fit_score) ||
    !isBoundedString(rawEvaluation.rationale, 5000) ||
    !Array.isArray(strengths) ||
    strengths.length > 20 ||
    !strengths.every((strength) => isBoundedString(strength, 500)) ||
    !Array.isArray(eligibilityRequirements) ||
    eligibilityRequirements.length > 25 ||
    !Array.isArray(risks) ||
    risks.length > 8 ||
    !Array.isArray(clarifications) ||
    clarifications.length > 8
  ) throw new Error('invalid response');

  const sourceRequirements = Array.isArray(tender.requirements) ? tender.requirements : [];
  const knownRequirementIds = new Set(
    sourceRequirements
      .map((requirement) => requirement?.id)
      .filter((id) => isBoundedString(id, 100))
  );
  if (eligibilityRequirements.length !== knownRequirementIds.size) {
    throw new Error('invalid response');
  }
  const sourceById = new Map(sourceRequirements.map((requirement) => [requirement?.id, requirement]));
  const sanitizedRequirements = eligibilityRequirements.map((requirement) => {
    if (
      !isObject(requirement) ||
      !isBoundedString(requirement.id, 100) ||
      !['compliant', 'partial', 'needs_review', 'not_met'].includes(requirement.status) ||
      typeof requirement.is_blocking !== 'boolean' ||
      !knownRequirementIds.has(requirement.id)
    ) throw new Error('invalid response');
    if (evidenceContractEnabled && (
      !validProfileEvidence(requirement.profile_evidence) ||
      !validDirectEvidence(requirement.id, requirement.profile_evidence) ||
      !validDirectStatus(requirement.id, requirement.status) ||
      !isBoundedString(requirement.assessment_reason, 1000) ||
      (requirement.status !== 'needs_review' && requirement.profile_evidence.length === 0)
    )) throw new Error('invalid response');
    const source = sourceById.get(requirement.id);
    const evidenceUnknown = referenceEvidenceUnknownIds.has(requirement.id);
    const evidenceAbsent = referenceEvidenceAbsentIds.has(requirement.id);
    const status = evidenceUnknown ? 'needs_review'
      : evidenceAbsent ? 'not_met' : requirement.status;
    const assessmentReason = evidenceUnknown ? referenceReviewReason
      : evidenceAbsent ? 'Das Unternehmensprofil bestätigt ausdrücklich, dass keine Referenzprojekte vorliegen.'
        : requirement.assessment_reason;
    const profileEvidence = evidenceUnknown || evidenceAbsent
      ? ['project_references_state'] : requirement.profile_evidence;
    return {
      id: requirement.id,
      status,
      is_blocking: status === 'not_met' &&
        (evidenceAbsent ? source?.is_critical === true
          : requirement.is_blocking || source?.is_critical === true),
      ...(evidenceContractEnabled ? {
        profile_evidence: profileEvidence,
        assessment_reason: assessmentReason,
      } : {}),
      ...(evidenceUnknown ? { review_reason: referenceReviewReason } : {}),
    };
  });
  if (!hasUniqueIds(sanitizedRequirements)) throw new Error('invalid response');

  const sanitizedRisks = risks.map((risk) => {
    if (
      !isObject(risk) ||
      !isBoundedString(risk.id, 100) ||
      !isBoundedString(risk.title, 200) ||
      !isBoundedString(risk.text, 2000) ||
      !['low', 'medium', 'high'].includes(risk.severity) ||
      !isBoundedString(risk.mitigation, 2000)
    ) throw new Error('invalid response');
    return Object.fromEntries(riskKeys.map((key) => [key, risk[key]]));
  });
  if (!hasUniqueIds(sanitizedRisks)) throw new Error('invalid response');

  const sanitizedClarifications = clarifications.map((clarification) => {
    if (
      !isObject(clarification) ||
      !isBoundedString(clarification.id, 100) ||
      !isBoundedString(clarification.question, 2000) ||
      !['medium', 'high'].includes(clarification.priority)
    ) throw new Error('invalid response');
    return Object.fromEntries(clarificationKeys.map((key) => [key, clarification[key]]));
  });
  if (!hasUniqueIds(sanitizedClarifications)) throw new Error('invalid response');

  const actualCounts = { compliant: 0, partial: 0, not_met: 0, needs_review: 0, blocking: 0 };
  for (const requirement of sanitizedRequirements) {
    actualCounts[requirement.status]++;
    if (requirement.is_blocking) actualCounts.blocking++;
  }
  actualBlockingCount = actualCounts.blocking;
  let unresolvedEvidence = knownRequirementIds.size === 0;
  for (const requirement of sanitizedRequirements) {
    const source = sourceById.get(requirement.id);
    if (requirement.status === 'needs_review'
      || (source?.is_critical === true && requirement.status === 'partial')) {
      unresolvedEvidence = true;
    }
  }
  const bidRecommendation = actualCounts.blocking > 0
    ? 'recommend_no_bid'
    : unresolvedEvidence
      ? 'needs_review'
      : rawEvaluation.strategic_fit_score >= 70
        ? 'recommend_bid'
        : rawEvaluation.strategic_fit_score >= 50 ? 'needs_review' : 'recommend_no_bid';
  evaluation = {
    strategic_fit_score: rawEvaluation.strategic_fit_score,
    ...(scoreMethodologyEnabled ? { score_components: rawEvaluation.score_components } : {}),
    bid_recommendation: bidRecommendation,
    rationale: rawEvaluation.rationale,
    strengths,
    eligibility_summary: {
      compliant_count: actualCounts.compliant,
      partial_count: actualCounts.partial,
      not_met_count: actualCounts.not_met,
      ...(actualCounts.needs_review > 0 ? { needs_review_count: actualCounts.needs_review } : {}),
      blocking_issues: actualCounts.blocking,
    },
    eligibility_requirements: sanitizedRequirements,
    risks: sanitizedRisks,
    clarifications: sanitizedClarifications,
  };
} catch {
  console.error('LLM_RESPONSE_INVALID_JSON');
  throw new Error('LLM_RESPONSE_INVALID_JSON');
}

// Coverage is workflow-owned metadata. Preserve validated blocker no-bids;
// otherwise apply the conservative override only after raw validation succeeds.
const coverage = tender.requirements_coverage;
const coverageIsValid =
  isExactObject(coverage, coverageKeys) &&
  typeof coverage.source_insufficient === 'boolean' &&
  typeof coverage.source_truncated === 'boolean' &&
  isNonnegativeInteger(coverage.source_char_count) &&
  isNonnegativeInteger(coverage.extracted_char_count) &&
  coverage.source_char_limit === 12000 &&
  coverage.extracted_char_count === Math.min(coverage.source_char_count, coverage.source_char_limit) &&
  coverage.source_truncated === (coverage.source_char_count > coverage.source_char_limit) &&
  isNonnegativeInteger(coverage.requirement_count) &&
  coverage.requirement_count === (Array.isArray(tender.requirements) ? tender.requirements.length : 0) &&
  coverage.requirement_limit === 25 &&
  typeof coverage.requirement_limit_reached === 'boolean' &&
  coverage.requirement_limit_reached === (coverage.requirement_count === coverage.requirement_limit);
const finalBidRecommendation = actualBlockingCount > 0
  ? evaluation.bid_recommendation
  : coverageIsValid &&
      !coverage.source_insufficient &&
      !coverage.source_truncated &&
      !coverage.requirement_limit_reached
    ? evaluation.bid_recommendation
    : 'needs_review';

const distance_km = $('geocode-distance').first().json.distance_km ?? null;
const distance_note = $('geocode-distance').first().json.distance_note ?? null;

return [{ json: {
  id: tenderId,
  strategic_fit_score: evaluation.strategic_fit_score,
  ...(scoreMethodologyEnabled ? { score_components: evaluation.score_components } : {}),
  bid_recommendation: finalBidRecommendation,
  rationale: evaluation.rationale,
  strengths: evaluation.strengths,
  eligibility_summary: evaluation.eligibility_summary,
  eligibility_requirements: evaluation.eligibility_requirements,
  risks: evaluation.risks,
  clarifications: evaluation.clarifications,
  processing_status: 'complete',
  distance_km,
  distance_note,
} }];

const evidenceContext = $('attach-requirement-evidence').first().json;
const payload = JSON.parse(evidenceContext.requirements_json || '{}');
const enriched = Array.isArray(payload.source_requirements) ? payload.source_requirements : [];
const byId = new Map(enriched.map((requirement) => [requirement.id, requirement]));
const sources = Array.isArray($json.reconciliation_source_requirements)
  ? $json.reconciliation_source_requirements : [];
return [{ json: {
  ...$json,
  company_profile: evidenceContext.company_profile,
  profile_evidence_contract: evidenceContext.profile_evidence_contract,
  requirement_evidence_fields: evidenceContext.requirement_evidence_fields,
  requirement_evidence_policy: evidenceContext.requirement_evidence_policy,
  bauort: evidenceContext.bauort,
  value_breakdown_note: evidenceContext.value_breakdown_note,
  reconciliation_source_requirements: sources.map((source) => byId.get(source.id) || source),
  reusable_company_evidence: Array.isArray(payload.reusable_company_evidence)
    ? payload.reusable_company_evidence : [],
} }];

const attached = $('attach-requirement-evidence').first().json;
const exactById = new Map((Array.isArray(attached.tender_requirement_evidence)
  ? attached.tender_requirement_evidence : []).map((item) => [item.requirement_id, item]));
const companyEvidence = Array.isArray(attached.company_requirement_evidence)
  ? attached.company_requirement_evidence : [];
const sourceRequirements = Array.isArray($('load-requirements').first().json.requirements)
  ? $('load-requirements').first().json.requirements : [];
const sourceById = new Map(sourceRequirements.map((item) => [item.id, item]));
let previous = $('load-requirements').first().json.eligibility_requirements;
if (typeof previous === 'string') {
  try { previous = JSON.parse(previous); } catch { previous = []; }
}
const validStatuses = new Set(['compliant', 'partial', 'needs_review', 'not_met']);
const previousById = new Map((Array.isArray(previous) ? previous : [])
  .filter((item) => item && typeof item.id === 'string' &&
    validStatuses.has(item.status) && typeof item.is_blocking === 'boolean')
  .map((item) => [item.id, item]));
const current = Array.isArray($json.eligibility_requirements) ? $json.eligibility_requirements : [];
const requirements = current.map((item) => {
  const source = sourceById.get(item?.id);
  const exact = exactById.get(item?.id);
  const evidence = attached.requirement_evidence_by_id?.[item?.id] || null;
  if (!evidence) return item;
  if (exact?.status === 'not_applicable') {
    const prior = previousById.get(item.id);
    if (!prior) return {
      ...item, status: 'needs_review', is_blocking: false,
      assessment_reason: 'Nicht zutreffend muss anhand der Quellanforderung geprüft werden.',
      requirement_evidence: [exact.evidence_id],
    };
    return {
      ...item,
      status: prior.status,
      is_blocking: prior.status === 'not_met' && prior.is_blocking === true,
      assessment_reason: typeof prior.assessment_reason === 'string'
        ? prior.assessment_reason : 'Die vorige Bewertung bleibt bestehen; nicht zutreffend wurde nicht automatisch übernommen.',
      requirement_evidence: [exact.evidence_id],
    };
  }
  const status = evidence.status === 'verified' ? 'compliant'
    : evidence.status === 'not_met' ? 'not_met'
      : evidence.status === 'in_progress' ? 'partial' : 'needs_review';
  return {
    ...item,
    status,
    is_blocking: status === 'not_met' && source?.is_critical === true,
    assessment_reason: [
      evidence.status === 'verified' ? 'Bestätigter Beleg'
        : evidence.status === 'not_met' ? 'Bestätigter Gegenbeleg'
          : evidence.status === 'in_progress' ? 'Nachweis in Bearbeitung' : 'Nachweis noch offen',
      evidence.title,
      evidence.note,
      'evidence_id=' + evidence.evidence_id,
    ].filter(Boolean).join(': ').slice(0, 1000),
    requirement_evidence: [evidence.evidence_id],
  };
});
const counts = { compliant: 0, partial: 0, not_met: 0, needs_review: 0, blocking: 0 };
for (const item of requirements) {
  if (validStatuses.has(item.status)) counts[item.status]++;
  if (item.is_blocking === true) counts.blocking++;
}
const score = Number.isInteger($json.strategic_fit_score) ? $json.strategic_fit_score : 50;
const unresolved = requirements.length === 0 || requirements.some((item) =>
  item.status === 'needs_review' || (sourceById.get(item.id)?.is_critical === true && item.status === 'partial'));
return [{ json: {
  ...$json,
  bid_recommendation: counts.blocking > 0 ? 'recommend_no_bid'
    : unresolved ? 'needs_review'
      : score >= 70 ? 'recommend_bid' : score >= 50 ? 'needs_review' : 'recommend_no_bid',
  eligibility_summary: {
    compliant_count: counts.compliant,
    partial_count: counts.partial,
    not_met_count: counts.not_met,
    ...(counts.needs_review > 0 ? { needs_review_count: counts.needs_review } : {}),
    blocking_issues: counts.blocking,
  },
  eligibility_requirements: requirements,
} }];

const summary = $json.eligibility_summary && typeof $json.eligibility_summary === 'object'
  && !Array.isArray($json.eligibility_summary) ? $json.eligibility_summary : {};
const cutoff = $('attach-requirement-evidence').first().json.evidence_cutoff_at;
return [{ json: {
  ...$json,
  eligibility_summary: {
    ...summary,
    evaluated_at: new Date().toISOString(),
    evidence_cutoff_at: typeof cutoff === 'string' ? cutoff : null,
  },
} }];

const eval_data = $('finalize-evaluation').first().json;
return [{ json: {
  id: eval_data.id,
  strategic_fit_score: eval_data.strategic_fit_score,
  bid_recommendation: eval_data.bid_recommendation,
  rationale: eval_data.rationale || '',
  strengths: eval_data.strengths || [],
  eligibility_summary: eval_data.eligibility_summary,
  eligibility_requirements: eval_data.eligibility_requirements || [],
  risks: eval_data.risks || [],
  clarifications: eval_data.clarifications || [],
  processing_status: 'complete'
} }];
